import java.sql.*; public class _Qry { public static void main(String[] a) throws Exception { Connection c = DriverManager.getConnection("jdbc:sqlserver://127.0.0.1:1433;databaseName=HSDZ_MES;encrypt=false", "yinjia", "Yinjia@2026"); Statement s = c.createStatement(); ResultSet r = s.executeQuery("SELECT TOP 5 [批号], [事件], [单据编号] FROM v_lot_trace ORDER BY id DESC"); int n = 0; while (r.next()) { n++; System.out.println(r.getString(1) + " | " + r.getString(2) + " | " + r.getString(3)); } System.out.println("rows(top5)=" + n); r = s.executeQuery("SELECT COUNT(*) FROM v_lot_trace"); r.next(); System.out.println("total=" + r.getInt(1)); ResultSet m = s.executeQuery("SELECT name FROM sys.columns WHERE object_id = OBJECT_ID('v_lot_trace') ORDER BY column_id"); StringBuilder cols = new StringBuilder(); while (m.next()) cols.append(m.getString(1)).append(","); System.out.println("cols: " + cols); } }